/**
 * 游戏自己的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        _collectNode:null,
        _popWin:null,
        _qiePing:null,
        _slotsArr:[],
        _slotsIndex:0,
        _bonus:null,
        _manage:null,
    },

    getCollectNode:function(){
        return this._collectNode
    },
    setCollectNode(script){
        this._collectNode = script
    },

    getPopWinManage(){
        return this._popWin
    },
    setPopWinManage(script){
        this._popWin = script
    },

    getQiePing(){
        return this._qiePing
    },
    setQiePing(script){
        this._qiePing = script
    },  

    addSlots(cmp){
        this._slotsArr.push(cmp);
    },

    setSlotsIndex(index){
        this._slotsIndex = index
    },

    //获得游戏的slots脚本
    GetSlotsScript:function(){
        return this._slotsArr[this._slotsIndex]
    },

    GetSlotsScriptById(idx){
        return this._slotsArr[idx]
    },

    getBonus(){
        return this._bonus
    },
    setBonus(script){
        this._bonus = script
    },  

    //deskInfo进入游戏获得的服务端数据
    init(deskInfo,gameId,gameJackpot){ //已重写
        this._super(deskInfo,gameId,gameJackpot)
        if (this._deskInfo.restFreeCount > 0) {
            this._slotsIndex = 1
        }else{
            this._slotsIndex = 0
        }
    },

    showSlot(){
        for (let i = 0; i < this._slotsArr.length; i++) {
            const slot = this._slotsArr[i];
            if(i == this._slotsIndex){
                slot.show()
            }else{
                slot.hide()
            }
        }
    },

    recoverySlot(){
        for (let i = 0; i < this._slotsArr.length; i++) {
            const slot = this._slotsArr[i];
            if(i == this._slotsIndex){
                slot.recovery()
            }else{
                slot.hide()
            }
        }
    },

    getManage(){
        return this._manage
    },
    setManage(script){
        this._manage = script
    },

    // update (dt) {},
});
