/**飞马座的崛起
 * 
*/
cc.Class({
    extends: cc.Component,

    properties: {
        _reels:[],
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        for (let i = 1; i < 6; i++) {
            let reel = cc.find("reels/reel"+i,this.node).addComponent("GenghisKhan_bounsReel")
            this._reels.push(reel)
            reel.init(i)
        }
    },

    start () {

    },

    showBonus(idx,result,callBack,stopIdx){
        for (let i = 0; i < this._reels.length; i++) {
            const reel = this._reels[i];
            reel.hide()
        }
        this._reels[idx].show(result,callBack,stopIdx)
    },

    // update (dt) {},
});
