/**
 * 弹窗管理
 */
cc.Class({
    extends: require("LMSlots_Bottom_Base"),

    properties: {

    },

    showTotalBet(isShow){
        cc.find("totalBetBg", this.node).active = isShow
    },

    //重写
    //显示按钮状态strState
    //"idle":空闲。 (所有按钮可以点击)
    //"moveing_1":旋转，结果还未返回。(所有按钮不可点击,spin按钮灰态)
    //"moveing_2":旋转，结果已经返回。(其它按钮不可点击,stop按钮可以点击)
    //"stoped":停止，但是还在播放加钱。(此时spin亮起来，其他按钮是灰态)
    //”unstoped“: 不能停止的操作。（stop按钮是灰态，其他按钮是灰态）
    ShowBtnsByState:function(strState){
        this._super(strState)
        if(strState == "moveing_2"){
            cc.vv.gameData.GetSlotsScript()._stopClick.active = true
        }else{
            cc.vv.gameData.GetSlotsScript()._stopClick.active = false
        }
    },

});
