
cc.Class({
    extends: cc.Component,

    properties: {
        qiepinGD:{
            default:null,
            type:cc.Node
        },
        qiepinQiu:{
            default:null,
            type:cc.Node
        },
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {

    },

    onDestroy(){

    },

    start () {

    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    showGongDian(callBack){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition_free)
            this.qiepinGD.active = true
            let show_popupSp = this.qiepinGD.getComponent(sp.Skeleton)
            show_popupSp.setAnimation(0,"animation",false)
            show_popupSp.setCompleteListener(()=>{
                this.qiepinGD.active = false
                sucess()
                show_popupSp.setCompleteListener(null)
            })
            await this.awaitTime(0.5)
            if(callBack){
                callBack()
            }
        });
    },

    showQiu(callBack){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition_map)
            this.qiepinQiu.active = true
            let show_popupSp = this.qiepinQiu.getComponent(sp.Skeleton)
            show_popupSp.setAnimation(0,"animation",false)
            show_popupSp.setCompleteListener(()=>{
                this.qiepinQiu.active = false
                sucess()
                show_popupSp.setCompleteListener(null)
            })
            await this.awaitTime(0.5)
            if(callBack){
                callBack()
            }
        });
    },

    // update (dt) {},
});
