/**飞马座的崛起
 * 
*/
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    SetSymbolIdx:function(idx){
        this._symbolIdx = idx;
        if(this._id === 2){
            this.node.zIndex = 150 - idx;
        }else{
            this.node.zIndex = 100 - idx;
        }
    },

    showZhaQiu(){
        return new Promise((success,failed)=>{
            if(this._id !== 3){
                success()
                return
            }
            let tempNode = cc.instantiate(this.node)
            tempNode.parent = cc.vv.gameData.GetSlotsScript()._stayNode
            tempNode.active = true
            let pos = this.node.convertToWorldSpaceAR(cc.v2(0,0))
            let endPos = cc.vv.gameData.GetSlotsScript()._stayNode.convertToNodeSpaceAR(pos)
            tempNode.position = endPos
            let node = cc.find("w14",tempNode)
            node.active = true
            let nodeSp = node.getComponent(sp.Skeleton)
            nodeSp.setAnimation(0,"animation3",true)
            this.scheduleOnce(()=>{
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bonus_boom)
                let animation = cc.find("zhaqiu",tempNode)
                animation.active = true
                let animationSp = animation.getComponent(sp.Skeleton)
                animationSp.setAnimation(0,"animation",false)
                animationSp.setCompleteListener(()=>{
                    tempNode.parent = null
                    success()
                    animationSp.setCompleteListener(null)
                }) 
            },1.5)
        })
    },

    playStopAnimation(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani){
            this._state = "stop";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            
            if(cfg.symbol[id].stop_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].stop_ani.name,false)
                    if(cfg.symbol[id].idle_ani){
                        nodeSp.addAnimation(0,cfg.symbol[id].idle_ani.name,true)
                    }
                }
            }
        }
    },

    //待机动画
    playidleAnimation(){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].idle_ani){
            this._state = "idle";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].idle_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].idle_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].idle_ani.name,true)
                }
            }
        }
        return isPlay
    },

    showSuo(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        let tempNode = cc.instantiate(this.node)
        tempNode.parent = cc.vv.gameData.GetSlotsScript()._stayNode
        tempNode.active = true
        let pos = this.node.convertToWorldSpaceAR(cc.v2(0,0))
        let endPos = cc.vv.gameData.GetSlotsScript()._stayNode.convertToNodeSpaceAR(pos)
        tempNode.position = endPos
        cc.find(cfg.symbol[id].node,tempNode).active = true
        let suo = cc.find("suo2",tempNode)
        suo.active = true
        let suoSp = suo.getComponent(sp.Skeleton)
        suoSp.setAnimation(0,"animation",false)
        suoSp.addAnimation(0,"animation2",true)
        suoSp.setCompleteListener(()=>{
            suoSp.setCompleteListener(null)
        })
    },

    changeWild(){
        this.ShowById(1)
        this.playTriggerAnimation()
    },

    ShowRandomSymbol_move:function(){
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(1,cfg.randomSymbols_move.length)
        let randVal = cfg.randomSymbols_move[randIdx-1]
        this.ShowById(randVal)
    },

    // update (dt) {},
});
