            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.mapfree_dialog_collect_show)
            this.showWin()
            let show_popup = cc.find("show_superBonusWinCoin",this.node)
            show_popup.active = true;
            let coin = cc.find("coin",show_popup)
            let collectBtn = cc.find("collectBtn",show_popup)
            coin.active = false
