/**
 * 墨西哥帅哥，奖池
 */
let jackpotNames = ['Mini','Minor','Major','Grand']  //节点名称
cc.Class({
    extends: require("LMSlots_PrizePool_Base"),

    properties: {
        _lastLockJackpot:0,  //最后一个被锁定的jackpot
    },

    start () {
        this._super()
        this.scheduleOnce(()=>{
            if(this.node.y + this.node.height/2 > cc.winSize.height / 2 - 74){
                let length = (this.node.y + this.node.height/2) - (cc.winSize.height / 2 - 20)
                this.node.y -= length
            }
        },0);
    },
    
    //各个节点上的解锁/锁定表现
    ShowNodeLockByNode:function(node,bLock,unLockBet,poolType,bInit){
        if(poolType > 0 && poolType < 4){
            let jpNodeName = jackpotNames[poolType]
            this.updataJackPoolLock(poolType,bLock)
            if(jpNodeName){
                let safeNode = cc.find('Canvas/safe_node')
                let jpNode = safeNode.getComponentInChildren('LMSlotMachine_PrizePool')
                if(jpNode){
                    let targetJpNode = cc.find('prizePool_'+jpNodeName,jpNode.node.parent)
                    if(targetJpNode){
                        let lbl_num = cc.find("lbl_num",targetJpNode)
                        let title = cc.find("spr_title",targetJpNode)
                        let liuguang = cc.find("liuguang",targetJpNode)
                        let lockEffect = cc.find("lockEffect",targetJpNode)
                        if(bLock){
                            if(!bInit){
                                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.jp_lock)
                                lockEffect.active = true
                                let lockEffectSp = lockEffect.getComponent(sp.Skeleton)
                                lockEffectSp.setAnimation(0,"animation"+(4 - poolType)+"_1",false)
                                lockEffectSp.setCompleteListener(()=>{
                                    lockEffectSp.setCompleteListener(null)
                                    lockEffect.active = false
                                })
                            }
                            lbl_num.getComponent(cc.Label).font = cc.vv.gameData.GetFontByName("theme228_base2")
                            targetJpNode.getComponent("ImgSwitchCmp").setIndex(1);
                            liuguang.active = false
                        }
                        else{
                            if(!bInit){
                                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.jp_unlock)
                                lockEffect.active = true
                                let lockEffectSp = lockEffect.getComponent(sp.Skeleton)
                                lockEffectSp.setAnimation(0,"animation"+(4 - poolType)+"_2",false)
                                lockEffectSp.setCompleteListener(()=>{
                                    lockEffectSp.setCompleteListener(null)
                                    lockEffect.active = false
                                })
                            }
                            lbl_num.getComponent(cc.Label).font = cc.vv.gameData.GetFontByName("theme228_base1")
                            targetJpNode.getComponent("ImgSwitchCmp").setIndex(0);
                            liuguang.active = true
                        }
                    }
                }
            }
        }
    },

    updataJackPoolLock(index,isLock){
        let tempIndex = index
        if(isLock){
            if(this._nowUpdatePool < tempIndex){
                return
            }
            this._nowUpdatePool = tempIndex
        }else{
            if(this._nowUpdatePool > tempIndex){
                return
            }
            this._nowUpdatePool = tempIndex
        }
        let safeNode = cc.find('Canvas/safe_node')
        let jpNode = safeNode.getComponentInChildren('LMSlotMachine_PrizePool')
        if(jpNode){
            for (let i = 1; i < jackpotNames.length; i++) {
                const jpNodeName = jackpotNames[i];
                let tips = cc.find('tips_'+jpNodeName,jpNode.node.parent)
                if(tips){
                    if(index === i){
                        if(isLock){
                            cc.find("lock",tips).active = true
                            cc.find("unlock",tips).active = false
                            tips.scale = 0
                            tips.stopAllActions()
                            cc.tween(tips)
                            .to(0.5,{scale:1},{easing:"backOut"})
                            .delay(0.5)
                            .to(0.5,{scale:0},{easing:"backIn"}).start()
                        }
                        else{
                            cc.find("lock",tips).active = false
                            cc.find("unlock",tips).active = true
                            tips.scale = 0
                            tips.stopAllActions()
                            cc.tween(tips)
                            .to(0.5,{scale:1},{easing:"backOut"})
                            .delay(0.5)
                            .to(0.5,{scale:0},{easing:"backIn"}).start()
                        }
                    }else{
                        tips.stopAllActions()
                        tips.scale = 0
                    }
                }
            }
        }
    },

    // update (dt) {},
});
