/**飞马座的崛起-bonusReel
 * 
*/
let speed = 1600
let g = 680
cc.Class({
    extends: cc.Component,

    properties: {
        _reelIdx:0,
        _result:[],
        _backReuslt:[],
        _symbols:[],
        _moveLength:0,
        _cfg:null,
        _remainingAmount:0,
        _randomVal:0,
        _mask:null,
        _bg:null,
        _stopTime:0,
        _bMoveing:false,  //是否转动
        _moveSpeed:0,
        _holder:null,
        _callBack:null,  //转完的回调函数
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._cfg = cc.vv.gameData.getGameCfg()
        this._mask = cc.find("mask",this.node)
        this._holder = cc.find("holder",this._mask)
    },

    start () {

    },

    init(index){
        this._reelIdx = index
        this._bg = cc.find("reels_bg/reel"+this._reelIdx,this.node.parent.parent)
        this.hide()
    },

    randomVal(){
        if(this._remainingAmount > 0){
            this._remainingAmount--
            return this._randomVal
        }
        let index = Global.random(0,this._cfg.randomSymbols_bonus.length - 1)
        let val = this._cfg.randomSymbols_bonus[index]
        this._randomVal = val
        this._remainingAmount = 3
        return this._randomVal
    },

    hide(){
        this.node.active = false
        this._bg.active = false
        if(this._callBack){
            this._callBack()
            this._callBack = null
        }
    },

    show(result,callBack,stopIdx){
        this._callBack = callBack
        this.node.active = true
        this._bg.active = true
        this.clearSymbols()
        this.showAnimation(result,stopIdx)
    },

    clearSymbols(){
        for (let i = 0; i < this._symbols.length; i++) {
            const symbol = this._symbols[i];
            symbol.node.parent = null
        }
        this._symbols = []
    },

    showAnimation(result,stopIdx){
        this.setResult(result,stopIdx)
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bonus_rise)
        let nodeSp = this._bg.getComponent(sp.Skeleton)
        nodeSp.setAnimation(0,"animation2",false)
        nodeSp.addAnimation(0,"animation3",true)
        nodeSp.setCompleteListener(()=>{
            this.startSpin()
            nodeSp.setCompleteListener(null)
        })
    },

    setResult(result,stopIdx){
        this._result = result
        this._backReuslt = []
        for (let i = stopIdx; i < result.length; i++) {
            this._backReuslt.push(result[i])
        }
    },

    startSpin(){
        if(this._symbols.length == 0){
            this.updateSymbol()
        }
        this._stopTime = 4.5
        this._bMoveing = true
        this._moveSpeed = speed
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bonus_roll)
    },

    update (dt) {
        this._stopTime -= dt
        if(this._bMoveing){
            if(this._symbols.length > 0){
                let pos = this._moveSpeed*dt
                for (let i = 0; i < this._symbols.length; i++) {
                    const symbol = this._symbols[i];
                    symbol.node.y -= pos
                }
                this._moveLength += pos
                if(this._moveLength > this._cfg.symbolSize.height){
                    this.updateSymbol()
                    this._moveLength -= this._cfg.symbolSize.height
                }
            }
        }
        if(this._stopTime <= 0){
            this._moveSpeed -= g*dt
            if(this._moveSpeed < 150){
                this._moveSpeed = 150
            }
        }
    },

    updateSymbol(){
        let tempNode = null
        if(this._symbols[0]){
            if(this._symbols[0].node.y <= -this._cfg.symbolSize.height/2){
                tempNode = this._symbols.shift()
            }
        }
        if(!tempNode){
            let node = cc.instantiate(cc.vv.gameData.GetPrefabByName(this._cfg.symbolPrefab))
            tempNode = node.addComponent(this._cfg.scripts.Symbols)
            tempNode.node.parent = this._mask
        }
        let id = this.randomVal()
        let resultId = null
        if(this._bMoveing && this._stopTime <= 2){
            resultId = this._result.shift()
            if(!resultId){
                this._bMoveing = false
                let lastNodePosY = this._holder.y - this._cfg.symbolSize.height/2
                let trueLastNodePosY = this._symbols[0].node.y
                let cha = lastNodePosY - trueLastNodePosY
                let time = -cha/this._moveSpeed
                if(time < 0){
                    time = 0
                }
                for (let i = 0; i < this._symbols.length; i++) {
                    const symbol = this._symbols[i];
                    let dstpos = symbol.node.y + cha  
                    cc.tween(symbol.node).to(time,{y:dstpos}).start()
                }
                this.scheduleOnce(()=>{
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bonus_stop)
                    this.hideAnimation()
                },time + 0.5)
            }
        }
        if(resultId){
            id = resultId
        }
        tempNode.ShowById(id)
        if(this._symbols.length > 0){
            tempNode.node.y = this._symbols[this._symbols.length - 1].node.y + this._cfg.symbolSize.height
        }else{
            tempNode.node.y = this._mask.height + this._cfg.symbolSize.height/2 + this._holder.y
        }
        this._symbols.push(tempNode)
    },

    hideAnimation(){
        let nodeSp = this._bg.getComponent(sp.Skeleton)
        nodeSp.setAnimation(0,"animation4",false)
        nodeSp.setCompleteListener(()=>{
            this.hide()
            nodeSp.setCompleteListener(null)
        })
        for (let i = 0; i < this._symbols.length; i++) {
            const symbol = this._symbols[i];
            cc.tween(symbol.node).to(0.5,{opacity:0}).start()
        }
        for (let i = 0; i < this._backReuslt.length; i++) {
            const id = this._backReuslt[i];
            let reel = cc.vv.gameData.GetSlotsScript()._reels[this._reelIdx - 1]
            let reelSymbol = reel._symbols[i]
            if(reelSymbol){
                reelSymbol.ShowById(id)
            }
        }
        cc.vv.gameData.getCollectNode().show()
    }
});
