cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {

    },

    InitCommComponent:function(){
        this.FitIPad()
        //BigWin
        this.node.addComponent("BigWin")
        //资源加载脚本
        let assetScp = cc.find("Canvas").getComponent("LMSlots_Asset_Base")
        cc.vv.gameData.SetAssetScript(assetScp)

        let safeNode = cc.find('safe_node',this.node)
        let cfg = cc.vv.gameData.getGameCfg()
        //sound
        let defSoundCmp = 'LMSlots_Sound'
        if (cfg.scripts.Sound) {
            defSoundCmp = cfg.scripts.Sound
        }
        this.node.addComponent(defSoundCmp)

        //顶部
        let node_top = cc.find('LMSlots_Top',safeNode)
        let script_top = node_top.addComponent(cfg.scripts.Top)
        script_top.Init()
        //底部
        let node_bottom = cc.find('LMSlots_Bottom',safeNode)
        let script_bottom = node_bottom.addComponent(cfg.scripts.Bottom)
        script_bottom.Init()
        //存到gamedata里面
        cc.vv.gameData.SetTopBottomScript(script_top,script_bottom)

        //slots
        let node_slots = cc.find('slots',safeNode)
        let script_slots = node_slots.addComponent(cfg.scripts.Slots)
        //存到gamedata里面
        cc.vv.gameData.addSlots(script_slots)
        let script_slotsfree = cc.find('slotsfree',safeNode).addComponent(cfg.scripts.Slots)
        //存到gamedata里面
        cc.vv.gameData.addSlots(script_slotsfree)
        let script_slotssuper = cc.find('slotssuper',safeNode).addComponent(cfg.scripts.Slots)
        //存到gamedata里面
        cc.vv.gameData.addSlots(script_slotssuper)

        //slot外的系统功能组建
        this.node.addComponent('LMSots_OtherSys')

        // 拼图功能
        if (cfg.puzzleCfg) {
            this.node.addComponent("LMSlots_Puzzle");
        }

        let slots = cc.find('Canvas/safe_node/slots')
        let collect = slots.getComponentInChildren("GenghisKhan_CollectNode")
        if(collect){
            cc.vv.gameData.setCollectNode(collect)
        }
        let popWin = safeNode.getComponentInChildren("GenghisKhan_Pop")
        if(popWin){
            cc.vv.gameData.setPopWinManage(popWin)
        }
        let qieping = safeNode.getComponentInChildren("GenghisKhan_qiePing")
        if(qieping){
            cc.vv.gameData.setQiePing(qieping)
        }
        let bonus = safeNode.getComponentInChildren("GenghisKhan_bouns")
        if(bonus){
            cc.vv.gameData.setBonus(bonus)
        }
        cc.vv.gameData.setManage(this.node.getComponent("GenghisKhan_manage"))
    },
    // LIFE-CYCLE CALLBACKS:

    StartSlot:function(){
        let script_slots = cc.vv.gameData._slotsArr
        for (let i = 0; i < script_slots.length; i++) {
            const element = script_slots[i];
            element.Init()
        }
    },

    // update (dt) {},
});
