cc.Class({
    extends: cc.Component,

    properties: {
        _suo:null,
        _clickNode:null,
        _pointList:[],
        _needBet:0,
        _collectLock:true,
        _pointIndex:0,
        _maxCount:0,
        _superJL:null,
        _tips:null,
        _sjt:null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._suo = cc.find("sjt_suo",this.node)
        this._clickNode = cc.find("clickNode",this.node)
        for (let i = 1; i < 7; i++) {
            let point = cc.find("point"+i,this.node)
            this._pointList.push(point)
        }
        this._clickNode.on("click",this.onClickNode,this)
        this._superJL = cc.find("superJL",this.node)
        this._tips = cc.find("tips",this.node)
        this._sjt = cc.find("sjt",this.node)
    },

    onDestroy(){

    },

    start () {

    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    isSuperBonus(){
        return this._pointIndex == this._maxCount
    },

    show(){
        cc.tween(this.node).to(0.5,{opacity:255}).start()
    },

    hide(){
        cc.tween(this.node).to(0.5,{opacity:0}).start()
    },

    setCollectData(collect,needbet){
        this._needBet = needbet
        this._pointIndex = collect.count || 0
        this._maxCount = collect.totalCount
        for (let i = 0; i < this._pointIndex; i++) {
            const element = this._pointList[i];
            cc.find("select",element).active = true
        }
        this.initCollectNode()
        if(this._maxCount - this._pointIndex == 1){
            this._superJL.active = true
        }else{
            this._superJL.active = false
        }
    },

    onClickNode(){
        if(cc.vv.gameData.GetSlotsScript()._isInFree){ //在免费游戏中不能修改押注
            return
        }
        if(cc.vv.gameData.GetSlotState() != 'idle'){
            return
        }
        if(cc.vv.gameData.GetAutoModelTime() > 0){
            return
        }
        if(this._tips.active){
            return
        }
        if(this._needBet <= cc.vv.gameData._deskInfo.mults.length){
            let curmult = cc.vv.gameData.GetBetIdx()
            if(curmult >= this._needBet){
                this.showTips()
            }else{
                let bottom = cc.vv.gameData.GetBottomScript()
                bottom.SetBetIdx(this._needBet)
            }
        }
    },

    showTips(){
        this._tips.active = true
        this._tips.scale = 0
        this._tips.stopAllActions()
        cc.tween(this._tips).to(0.2,{scale:1},{easing:"backOut"}).delay(2).to(0.2,{scale:0},{easing:"backIn"}).call(()=>{
            this._tips.active = false
        }).start()
    },

    initCollectNode(){
        let curmult = cc.vv.gameData.GetBetIdx()
        if(curmult >= this._needBet){  //已经解锁
            this._collectLock = false
            this._suo.active = false
            this.showTips()
        }else{
            this._suo.active = true
            let spineSp = this._suo.getComponent(sp.Skeleton)
            spineSp.setAnimation(0,"animation2",true)
            this._collectLock = true
        }
    },

    changeCollectNode(){
        let curmult = cc.vv.gameData.GetBetIdx()
        if(curmult >= this._needBet){  //已经解锁
            if(this._collectLock){
                this._collectLock = false
                let spineSp = this._suo.getComponent(sp.Skeleton)
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.collect_unlock)
                this._suo.active = true
                spineSp.setAnimation(0,"animation3",false)
                spineSp.setCompleteListener(()=>{
                    this._suo.active = false
                    spineSp.setCompleteListener(null)
                })
            }
        }else{
            if(!this._collectLock){
                this._collectLock = true
                let spineSp = this._suo.getComponent(sp.Skeleton)
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.collect_lock)
                this._suo.active = true
                spineSp.setAnimation(0,"animation1",false)
                spineSp.addAnimation(0,"animation2",true)
            }
        }
    },

    async addPoint(idxList){
        let curmult = cc.vv.gameData.GetBetIdx()
        if(curmult < this._needBet){  //未解锁
            return
        }
        this._pointIndex++
        if(this._pointIndex > this._maxCount){
            this._pointIndex = this._maxCount
        }
        let point = this._pointList[this._pointIndex-1]
        let pointPos = point.convertToWorldSpaceAR(cc.v2(0,0))
        let endPos = cc.vv.gameData.getManage()._collectFree.convertToNodeSpaceAR(pointPos)
        for (let i = 0; i < idxList.length; i++) {
            const idx = idxList[i];
            let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(idx)
            if(symbol){
                let symbolPos = symbol.node.convertToWorldSpaceAR(cc.v2(0,0))
                let startPos = cc.vv.gameData.getManage()._collectFree.convertToNodeSpaceAR(symbolPos)
                let lizi = cc.instantiate(cc.vv.gameData.GetPrefabByName("scattershouji"))
                lizi.parent = cc.vv.gameData.getManage()._collectFree
                lizi.position = startPos
                cc.tween(lizi).to(0.5,{position:endPos}).call(()=>{
                    lizi.parent = null
                }).start()
            }
        }
        await this.awaitTime(0.5)
        cc.find("select",point).active = true
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.collect_light)
        if(this._maxCount - this._pointIndex == 1){
            this._superJL.active = true
        }else{
            this._superJL.active = false
        }
        if(this._pointIndex >= this._maxCount){  //触发superGame
            await this.awaitTime(0.2)
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.collect_full)
            let sjtSP = this._sjt.getComponent(sp.Skeleton)
            sjtSP.setAnimation(0,"animation2",false)
            sjtSP.addAnimation(0,"animation1",true)
        }
    },

    resetCollect(){
        for (let i = 0; i < this._pointList.length; i++) {
            const element = this._pointList[i];
            cc.find("select",element).active = false
        }
        this._pointIndex = 0
        this._superJL.active = false
    }

    // update (dt) {},
});
